import os
from dsl import *

_D = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'dbdata')
_NAMES = ['user', 'class', 'class_user_link', 'task', 'test', 'test_task_link', 'test_class_user_link', 'test_attempt', 'task_attempt']
FILESETS['db'] = {n + '.csv': open(os.path.join(_D, n + '.csv'), encoding='utf-8', newline='').read().replace('\r\n', '\n') for n in _NAMES}


def _src(n):
    return open(os.path.join(_D, n), encoding='utf-8').read()


MINI = 'имя,оценка\nАня,5\nБоря,4\nВера,5\n'
DATES = 'id,дата\n1,05.03.2024 13:04:27\n2,21.06.2024 10:00:00\n3,04.06.2025 15:52:54\n'


def build():
    terms1 = [
        ('csv', 'Формат текстового файла для таблиц: каждая строка файла это строка таблицы, а значения в ней разделены запятыми. Первая строка обычно содержит названия столбцов.\n\nПример:\nимя,оценка\nАня,5'),
        ('csv.reader', 'Объект из модуля csv: принимает открытый файл и выдаёт строки таблицы по одной, каждую в виде списка строк. Правильно разбирает значения в кавычках, внутри которых есть запятые.\n\nПример:\nimport csv\nreader = csv.reader(["Аня,5"])\nprint(list(reader))\nВывод:\n[[\'Аня\', \'5\']]'),
        ('next', 'Функция: берёт у итератора следующее значение. Если применить к csv.reader, получим следующую строку таблицы. Так пропускают строку заголовка.\n\nПример:\nit = iter([10, 20])\nprint(next(it))\nВывод:\n10'),
        ('datetime', 'Модуль для работы с датой и временем. Из него импортируют класс datetime: from datetime import datetime. Даты можно сравнивать, а значит и сортировать.\n\nПример:\nfrom datetime import datetime\nprint(datetime(2024, 3, 5) < datetime(2025, 1, 1))\nВывод:\nTrue'),
        ('strptime', 'Метод datetime.strptime(текст, шаблон): превращает строку с датой в объект datetime по шаблону. В шаблоне %d день, %m месяц, %Y год из четырёх цифр, %H часы, %M минуты, %S секунды.\n\nПример:\nfrom datetime import datetime\nd = datetime.strptime("05.03.2024", "%d.%m.%Y")\nprint(d.year)\nВывод:\n2024'),
        ('strftime', 'Метод объекта datetime: превращает дату обратно в строку по шаблону. %y даёт год из двух цифр.\n\nПример:\nfrom datetime import datetime\nd = datetime(2024, 3, 5)\nprint(d.strftime("%d.%m.%y"))\nВывод:\n05.03.24'),
    ]
    body1 = '''
<p>Данные в реальных программах редко приходят по одному числу. Чаще это таблицы: список учеников, список заданий, история ответов. Простейший способ хранить таблицу в файле называется [[csv|csv]]: одна строка файла равна одной строке таблицы, значения разделены запятыми.</p>
<pre class="out">имя,оценка
Аня,5
Боря,4
Вера,5</pre>
<p>Первая строка здесь заголовок: названия столбцов. Остальные строки сами данные.</p>

<h3>Читаем таблицу</h3>
<p>Можно было бы прочитать файл и разрезать каждую строку методом split(","), но тогда сломаются значения, в которых есть запятая внутри кавычек. Поэтому берут готовый модуль csv и его [[csv.reader|csv.reader]]. Он выдаёт строки таблицы по одной, каждую как список строк.</p>
''' + ex('''import csv
with open("marks.csv", encoding="utf-8") as f:
    reader = csv.reader(f)
    for row in reader:
        print(row)''', files={'marks.csv': MINI}) + '''
<p>Видно две вещи. Заголовок тоже пришёл как строка. И числа тоже строки: <code>'5'</code>, а не <code>5</code>, их нужно переводить через int.</p>
<p>Заголовок пропускают вызовом [[next|next]]: он забирает у reader одну строку, и цикл дальше идёт уже по данным. А если нужна вся таблица сразу, reader превращают в список:</p>
''' + ex('''import csv
with open("marks.csv", encoding="utf-8") as f:
    reader = csv.reader(f)
    next(reader)
    rows = list(reader)
print(rows)
print(sum(int(r[1]) for r in rows))''', files={'marks.csv': MINI}) + '''
<p>Список строк удобно один раз прочитать в функцию, а дальше работать с ним как с обычным списком: фильтровать списочными выражениями, сортировать, считать. Файл закрывается сам, когда закончится блок with:</p>
''' + ex('''import csv

def read(name):
    with open(name, encoding="utf-8") as f:
        reader = csv.reader(f)
        next(reader)
        return list(reader)

rows = read("marks.csv")
print([r[0] for r in rows if r[1] == "5"])''', files={'marks.csv': MINI}) + '''
<h3>Даты</h3>
<p>В таблицах даты записаны текстом, например <code>05.03.2024 13:04:27</code>. Как текст их сравнивать нельзя: строка «21.06.2024» окажется меньше «04.06.2025» только случайно, а «05.03.2025» уже будет меньше «21.06.2024». Нужно превратить текст в настоящую дату. Для этого есть модуль [[datetime|datetime]] и метод [[strptime|strptime]]: ему отдают текст и шаблон, в котором показано, где в тексте день, месяц, год и так далее.</p>
''' + ex('''from datetime import datetime
d = datetime.strptime("05.03.2024 13:04:27", "%d.%m.%Y %H:%M:%S")
print(d)
print(d.year, d.month, d.day)''') + '''
<p>Буквы в шаблоне: <code>%d</code> день, <code>%m</code> месяц, <code>%Y</code> год (4 цифры), <code>%H</code> часы, <code>%M</code> минуты, <code>%S</code> секунды. Всё остальное (точки, двоеточия, пробелы) в шаблоне должно совпадать с текстом буква в букву.</p>
<p>Даты можно сравнивать операциями <code>&lt;</code> и <code>&gt;</code>, а ещё использовать как ключ сортировки. Обратное превращение, из даты в текст, делает [[strftime|strftime]]. С ним можно записать дату в другом формате, например с годом из двух цифр (<code>%y</code>):</p>
''' + ex('''import csv
from datetime import datetime

with open("dates.csv", encoding="utf-8") as f:
    reader = csv.reader(f)
    next(reader)
    rows = list(reader)

rows.sort(key=lambda r: datetime.strptime(r[1], "%d.%m.%Y %H:%M:%S"), reverse=True)
for r in rows:
    d = datetime.strptime(r[1], "%d.%m.%Y %H:%M:%S")
    print(r[0], d.strftime("%d.%m.%y"))''', files={'dates.csv': DATES}) + '''
<p>Ключ сортировки может быть кортежем: если даты двух строк совпали, сработает второй элемент кортежа, например номер строки. Так порядок получается однозначным.</p>
'''
    th1 = th('Таблицы CSV и даты', terms1, body1)

    fl1 = fl('Вопросы: CSV и даты', [
        q('Что нужно сделать, чтобы пропустить строку заголовка у csv.reader?', 'Вызвать next(reader) перед циклом', ['Вызвать reader.skip()', 'Написать reader[0] = None', 'Ничего: reader пропускает заголовок сам'], 'Функция next забирает у reader первую строку, и цикл дальше идёт по данным. Сам reader заголовок не отличает от остальных строк: для него это просто первая строка файла.'),
        q('Что содержит rows[1][0], если rows = [["Аня", "5"], ["Боря", "4"]]?', 'Боря', ['Аня', '4', '5'], 'Сначала rows[1] выбирает вторую строку таблицы, то есть список ["Боря", "4"], потом [0] берёт в нём первый элемент.'),
        qo('Что выведет программа?', 'import csv\nrows = list(csv.reader(["a,1", "b,2"]))\nprint(rows[0][1] + rows[1][1])', ['3', 'Ошибка', '15'], 'Значения из csv.reader это строки. Строки складываются склейкой: "1" + "2" даёт "12". Чтобы сложить числа, нужно было написать int(...).'),
        q('Каким будет тип значения r[1], если r строка таблицы, прочитанная csv.reader?', 'str', ['int', 'float', 'datetime'], 'csv.reader ничего не угадывает: все значения приходят строками. Числа переводят через int или float, даты через strptime.'),
        qo('Что выведет программа?', 'from datetime import datetime\nd = datetime.strptime("07.11.2023", "%d.%m.%Y")\nprint(d.month)', ['7', '2023', '12'], 'Шаблон %d.%m.%Y говорит: сначала день, потом месяц, потом год. Значит день 7, месяц 11, год 2023. Поле month содержит 11.'),
        qo('Что выведет программа?', 'from datetime import datetime\nd = datetime(2024, 3, 5)\nprint(d.strftime("%d.%m.%y"))', ['2024.03.05', '05.03.2024', '03.05.24'], '%d это день (05), %m месяц (03), %y год из двух цифр (24). Точки между ними мы расставили сами в шаблоне.'),
        q('Почему даты нельзя сравнивать как строки вида «дд.мм.гггг»?', 'Сравнение идёт слева направо: сначала день, а не год', ['Строки вообще нельзя сравнивать', 'Python не умеет сравнивать цифры', 'Точки в строке мешают сравнению'], 'Строка "05.03.2025" окажется меньше "21.06.2024", потому что сначала сравнивается день: 05 меньше 21. Настоящие даты после strptime сравниваются правильно.'),
        qo('Что выведет программа?', 'from datetime import datetime\na = datetime.strptime("05.03.2025", "%d.%m.%Y")\nb = datetime.strptime("21.06.2024", "%d.%m.%Y")\nprint(a > b)', ['False', 'Ошибка', 'None'], 'После превращения в datetime сравнивается полная дата: 2025 год позже 2024. Поэтому a > b верно, выводится True.'),
    ])

    terms2 = [
        ('идентификатор', 'Число (id), которое однозначно определяет строку в таблице. По нему строки разных таблиц связывают друг с другом.\n\nПример:\nusers = {"1": "Аня", "2": "Боря"}\nprint(users["2"])\nВывод:\nБоря'),
        ('связующая таблица', 'Таблица, в которой каждая строка говорит «объект A связан с объектом B». Например: ученик 5 числится в классе 3. Она хранит только идентификаторы.\n\nПример:\nlinks = [["1", "3", "5"]]\nprint(links[0][1])\nВывод:\n3'),
        ('JSON-ответ', 'Результат работы программы в виде вложенных словарей и списков, записанный через json.dumps. Так программы обмениваются данными, например интерфейс и сервер.\n\nПример:\nimport json\nprint(json.dumps({"a": [1, 2]}))\nВывод:\n{"a": [1, 2]}'),
    ]
    body2 = '''
<p>Теперь посмотрим на то, как таблицы живут вместе. Представь школьный сервис с заданиями. В нём не одна огромная таблица, а несколько небольших, а связаны они [[идентификатор|идентификаторами]]: у каждой строки есть число <code>id</code> в первом столбце, а другие таблицы ссылаются на него.</p>
<p>Например, в таблице <code>test.csv</code> лежат только номера и названия тестов:</p>
<pre class="out">id,title
1,Алгоритмы
2,Интернет</pre>
<p>А кто и когда получил какой тест, записано в другой таблице. В ней нет названия, только номер теста. Такие таблицы называют [[связующая таблица|связующими]]:</p>
<pre class="out">id,test_id,class_user_link_id,datetime_started,datetime_ended
1,1,1,21.06.2024 10:00:00,28.06.2024 23:59:59</pre>
<p>Чтобы получить название, нужно по <code>test_id</code> найти строку в <code>test.csv</code>. Если делать это поиском по списку каждый раз, программа будет медленной и громоздкой. Лучше один раз собрать словарь «id → значение» словарным выражением:</p>
''' + ex('''tests = [["1", "Алгоритмы"], ["2", "Интернет"]]
titles = {r[0]: r[1] for r in tests}
given = [["1", "2"], ["2", "1"]]
for g in given:
    print(titles[g[1]])''') + '''
<p>Обрати внимание: идентификаторы из файла это строки. Если в одном месте сравнить <code>"2"</code> с числом <code>2</code>, условие не сработает. Нужно либо везде оставлять строки, либо везде переводить в int.</p>

<h3>Цепочка запросов</h3>
<p>Задача «получить данные по запросу» почти всегда выглядит как цепочка шагов: из запроса мы знаем один идентификатор, находим по нему строку в первой таблице, берём из неё следующий идентификатор, ищем его во второй и так далее. В нашей учебной базе, например, путь такой: пара «ученик и класс» даёт строку в таблице связей, она даёт назначенные тесты, они дают попытки, а попытки дают ответы на задания.</p>
<p>Составляй такую цепочку на бумаге до написания кода: какой идентификатор у меня есть, в какой таблице он встречается, какой новый идентификатор там лежит.</p>

<h3>Ответ в формате JSON</h3>
<p>Когда результат нужно отдать другой программе (например, интерфейсу сайта), его выводят в формате JSON. Из прошлой темы мы знаем: собираем вложенные словари и списки, а печатаем через <code>json.dumps</code>. Параметр <code>indent=2</code> делает вывод читаемым, а <code>ensure_ascii=False</code> оставляет русские буквы русскими. Такой вывод и называют [[JSON-ответ|JSON-ответом]].</p>
''' + ex('''import json
answer = {"user": {"id": 2, "name": "Мария"}, "tests": [{"title": "Интернет", "done": True}]}
print(json.dumps(answer, indent=2, ensure_ascii=False))''') + '''
<p>Тип значения в JSON важен: число <code>2</code> и строка <code>"2"</code> это разные вещи. Если по условию нужно число, строку нужно перевести через int до того, как положить её в словарь.</p>
'''
    th2 = th('Связанные таблицы и ответ JSON', terms2, body2)

    fl2 = fl('Вопросы: связи и JSON', [
        q('Для чего нужен словарь вида {r[0]: r[1] for r in rows} при работе с таблицами?', 'Чтобы по id сразу получать значение без перебора', ['Чтобы отсортировать таблицу', 'Чтобы удалить заголовок', 'Чтобы перевести строки в числа'], 'Словарь отвечает на вопрос «чему равно значение для этого id» за один шаг. Поиск перебором по списку на каждой строке был бы медленнее и длиннее.'),
        qo('Что выведет программа?', 'ids = {"1": "Аня", "2": "Боря"}\nprint(ids.get(2))', ['Боря', 'Аня', 'Ошибка'], 'Ключи в словаре строки "1" и "2", а мы ищем число 2. Это другой ключ, и метод get вернёт None. Идентификаторы из файла нужно сравнивать как строки или везде переводить в int.'),
        q('Почему идентификатор, прочитанный из csv, нельзя сравнить с числом через ==?', 'Он строка, а строка "2" не равна числу 2', ['Идентификаторы нельзя сравнивать', 'В csv хранятся только дробные числа', 'Сравнение работает только для даты'], 'Всё из csv.reader приходит строками. Условие "2" == 2 всегда ложно, поэтому нужно привести типы: либо int(r[0]) == 2, либо r[0] == "2".'),
        qo('Что выведет программа?', 'import json\nprint(json.dumps({"id": int("7")}))', ['{"id": 7}', '{"id": "7"}', '{id: 7}'], 'int("7") даёт число 7, а число в JSON пишется без кавычек. Если оставить строку "7", то в выводе будут кавычки.'),
        q('Что делает параметр ensure_ascii=False в json.dumps?', 'Оставляет русские буквы, а не коды вида \\u041f', ['Убирает пробелы из вывода', 'Сортирует ключи словаря', 'Добавляет отступы'], 'По умолчанию json.dumps записывает любые не латинские символы кодами \\uXXXX. С ensure_ascii=False текст остаётся читаемым.'),
        q('Какую строку нужно написать, чтобы JSON-вывод получил отступы в два пробела?', 'json.dumps(data, indent=2)', ['json.dumps(data, space=2)', 'json.dumps(data, tab=2)', 'json.dumps(data).indent(2)'], 'За отступы отвечает именованный параметр indent. Число показывает, сколько пробелов добавлять на каждом уровне вложенности.'),
    ])

    # ----------------- задания -----------------
    s1 = '''
import csv

names = ["user", "class", "class_user_link", "task", "test", "test_task_link", "test_class_user_link", "test_attempt", "task_attempt"]
for name in names:
    with open(name + ".csv", encoding="utf-8") as f:
        reader = csv.reader(f)
        next(reader)
        print(len(list(reader)))
'''
    t1 = task('Этап 1: проверка данных. В папке лежат 9 файлов в формате csv: user.csv, class.csv, class_user_link.csv, task.csv, test.csv, test_task_link.csv, test_class_user_link.csv, test_attempt.csv и task_attempt.csv. В каждом первая строка это заголовок. Выведи по одному числу в строке: количество строк с данными (без заголовка) в каждом из файлов, именно в таком порядке. Ввода нет.',
              'Заведи список с названиями без расширения. В цикле for открой файл name + ".csv" через with open(..., encoding="utf-8"), создай csv.reader, пропусти заголовок через next(reader) и напечатай len(list(reader)). Не забудь указать encoding="utf-8", иначе русские буквы могут прочитаться неверно.',
              s1, [''], files='db')

    t2 = task('Этап 2: тесты ученика. На вход подаётся строка «user_id class_id»: номер ученика и номер его класса. Ученик в классе записан в таблице class_user_link.csv (столбцы id, class_id, user_id): найди его строку, её id нужен дальше. Тесты, назначенные ученику, хранятся в test_class_user_link.csv (столбцы id, test_id, class_user_link_id, datetime_started, datetime_ended). Название теста лежит в test.csv (id, title). Тест считается завершённым, если для строки назначения в test_attempt.csv (id, test_class_user_link_id, flag_is_finished, ...) стоит TRUE. Выведи в первой строке X/Y, где X число завершённых тестов, а Y число всех назначенных. Далее по строке на каждый тест, от самого нового к самому старому (по datetime_started, при равенстве от большего id): название, дата назначения в формате дд.мм.гг, и TRUE или FALSE (завершён ли).',
              'Шаги: 1) прочитай входную строку: user_id, class_id = input().split(). 2) В class_user_link.csv найди строку, где r[1] == class_id и r[2] == user_id, возьми r[0]. 3) Из test_class_user_link.csv оставь строки, где r[2] равно этому числу. 4) Словарь названий: {r[0]: r[1] for r in read("test.csv")}. 5) Словарь завершённости: {r[1]: r[2] for r in read("test_attempt.csv")} (ключ это id назначения). 6) Отсортируй назначения по ключу (datetime.strptime(r[3], "%d.%m.%Y %H:%M:%S"), int(r[0])) с reverse=True. 7) Завершённых тестов считай через sum(1 for ... if ... == "TRUE"). 8) Дату выводи через strftime("%d.%m.%y"). Функцию read(name) с csv.reader и next напиши один раз сверху.',
              _src('s2.py'), ['2 2', '18 8', '194 14', '174 14', '1 1', '11 1'], files='db')

    t3 = task('Этап 3: последний тест. На вход подаётся «user_id class_id», как раньше. Возьми самый новый назначенный ученику тест (порядок как на прошлом этапе). Для него найди попытку в test_attempt.csv (по test_class_user_link_id), а задания теста в test_task_link.csv (id, test_id, task_id, order_number), отсортированные по order_number. Ответы ученика лежат в task_attempt.csv (id, task_id, test_attempt_id, answer, datetime_started, time_spent), верный ответ в task.csv (id, text, correct_answer). Пустой answer означает, что на задание не ответили. Выведи: в первой строке прогресс и точность в виде «P% C%», где P процент заданий, на которые ответили, от всех заданий теста, а C процент верных ответов от числа ответов; оба округли до одного знака после точки. Далее по строке на каждое задание теста по порядку: «порядок ответ id_задания», где ответ это TRUE (верно), FALSE (неверно) или ? (нет ответа). В последней строке суммарное время ответов (time_spent в секундах) в формате чч:мм:сс.',
              'Продолжай код прошлого этапа. Попытка: [r[0] for r in read("test_attempt.csv") if r[1] == id_назначения][0]. Задания теста: строки test_task_link, где r[1] == test_id; сортируй по int(r[3]). Ответы собери словарём {r[1]: r for r in read("task_attempt.csv") if r[2] == attempt_id}: по id задания найдём строку. Если строки нет или r[3] == "", это «?». Иначе сравни r[3] с верным ответом из словаря {r[0]: r[2] for r in read("task.csv")}. Процент: round(часть * 100 / целое, 1), а выводи через f"{p:.1f}%". Время: seconds // 3600, seconds % 3600 // 60, seconds % 60 с форматом :02d.',
              _src('s3.py'), ['2 2', '106 16', '1 1', '11 1'], files='db')

    ts1 = ts('Задания: обработка данных', [t1, t2, t3])

    proj = pj('Обработка запроса с интерфейса',
              'Сервис обучения хранит данные в девяти csv-файлах (они лежат рядом с программой, в каждом первая строка заголовок): user.csv (id, role, first_name, middle_name, last_name, ...), class.csv, class_user_link.csv (id, class_id, user_id), task.csv (id, text, correct_answer), test.csv (id, title), test_task_link.csv (id, test_id, task_id, order_number), test_class_user_link.csv (id, test_id, class_user_link_id, datetime_started, datetime_ended), test_attempt.csv (id, test_class_user_link_id, flag_is_finished, datetime_started, datetime_ended) и task_attempt.csv (id, task_id, test_attempt_id, answer, datetime_started, time_spent). Интерфейс присылает запрос: строку «user_id class_id». Выведи полный ответ в формате JSON (json.dumps с indent=2 и ensure_ascii=False). Структура: объект с ключами user, progress и tests. user: user_id (число), full_name (фамилия, пробел, имя) и class_id (число). progress: tests_completed (завершённых тестов), tests_total (всего назначенных) и accuracy_average_percent (среднее арифметическое значений correct_percent по всем тестам, округлить до одного знака). tests: список всех назначенных тестов от самого нового к самому старому (по datetime_started, при равенстве по большему id назначения). Для каждого теста: test_id (число), title, tasks (список объектов order_number, task_id, is_correct, где is_correct это строка "TRUE", "FALSE" или "?" — так же, как на прошлом этапе), progress_percent и correct_percent (округлены до одного знака; если ответов нет, correct_percent равен 0.0), time (чч:мм:сс, суммарное время ответов) и date_assigned (дд.мм.гг). Задания внутри теста идут по order_number. Тест считается завершённым, если для него в test_attempt.csv стоит TRUE. Если ответов в тесте нет, прогресс считается 0.0.',
              'Собирай ответ по частям. Сначала возьми код этапов 2 и 3 как основу. Внутри цикла по назначенным тестам (уже отсортированных от нового к старому) для каждого теста посчитай то, что на этапе 3 считалось только для последнего: список заданий, ответы, проценты, время. Результат цикла: словарь test с нужными ключами, а все словари складывай в список tests. Числа id переводи через int, чтобы в JSON они были без кавычек. full_name: person[4] + " " + person[2], где person строка из user.csv (индексы: 2 имя, 4 фамилия). Среднюю точность считай через sum(t["correct_percent"] for t in tests) / len(tests). Для скорости прочитай каждый файл один раз в начале программы (в переменную), а не внутри цикла. Если процент вычисляется делением на количество ответов, учти случай нуля ответов: деление на 0 даст ошибку, поэтому сначала проверь условие. В конце: print(json.dumps(result, indent=2, ensure_ascii=False)).',
              _src('s4.py'), ['2 2', '18 8', '194 14', '106 16', '1 1', '11 1', '174 14'], bonus=100, files='db')

    return topic('Обработка запроса с интерфейса', 'csv, datetime, связи между таблицами, JSON', [th1, fl1, th2, fl2, ts1, proj])
